import local.thor.bilichannels.*;import org.json.*;
public class PgcModelsTest {
 static int count;static void check(boolean ok,String name){count++;if(!ok)throw new AssertionError(name);}interface Work{void run()throws Exception;}static void fails(Work f,String name)throws Exception{try{f.run();throw new AssertionError(name);}catch(java.io.IOException expected){count++;}}
 static JSONObject episode(int id,int cid,String title)throws Exception{return new JSONObject().put("id",id).put("cid",cid).put("aid",99).put("bvid","BV15i421v7FQ").put("title",title).put("duration",125000).put("dimension",new JSONObject().put("width",1920).put("height",1080));}
 public static void main(String[] args)throws Exception{
  check(PgcModels.category(3).equals("纪录片"),"category");check(PgcModels.TYPES.length==PgcModels.NAMES.length,"category labels");
  JSONObject data=new JSONObject().put("list",new JSONArray().put(new JSONObject().put("season_id",11).put("title","<em>测试</em>&amp;作品").put("cover","//cdn.test/a.jpg").put("season_type",3)).put(new JSONObject().put("season_id",11).put("title","重复")).put(new JSONObject().put("season_id",0).put("title","无效"))).put("num",1).put("has_next",1);
  PgcModels.Page page=PgcModels.page(data,1,1);check(page.items.size()==1,"dedup and valid identity");check(page.items.get(0).title.equals("测试&作品"),"plain title");check(page.items.get(0).cover.startsWith("https://"),"secure cover");check(page.more,"server pagination");fails(()->PgcModels.page(data,2,1),"wrong page");fails(()->PgcModels.page(new JSONObject(),1,1),"missing list");
  data.put("has_next",false);check(!PgcModels.page(data,1,1).more,"boolean eof");JSONObject search=new JSONObject().put("result",data.getJSONArray("list")).put("page",2).put("numPages",2);check(!PgcModels.page(search,2,1).more,"search eof");
  check(PgcModels.checked(new JSONObject().put("code",0).put("result",data))==data,"result envelope");check(PgcModels.checked(new JSONObject().put("code",0).put("data",data))==data,"data envelope");fails(()->PgcModels.checked(new JSONObject().put("code",-10403)),"permission failure");fails(()->PgcModels.checked(new JSONObject().put("code",0)),"missing envelope");
  JSONObject season=new JSONObject().put("season_id",11).put("title","纪录片").put("type",3).put("evaluate","简介").put("episodes",new JSONArray().put(episode(21,101,"1")).put(episode(22,102,"2"))).put("section",new JSONArray().put(new JSONObject().put("title","预告").put("episodes",new JSONArray().put(episode(21,101,"重复")).put(episode(23,103,"预告片")))));
  PgcModels.Season parsed=PgcModels.season(season);check(parsed.episodes.size()==3,"dedup extras");Video one=parsed.episodes.get(0),two=parsed.episodes.get(1);check(one.pgc()&&one.episodeId==21&&one.seasonId==11,"episode identity");check(one.mediaKey().equals("ep21_101")&&!one.mediaKey().equals(two.mediaKey()),"independent resume identity");check(one.duration==125,"milliseconds to seconds");check(one.width==1920&&one.height==1080,"actual dimensions");check(one.pgcEpisodes==parsed.episodes,"shared episode collection");check(parsed.episodes.get(2).episodeTitle.startsWith("预告"),"section title");check(one.description.equals("简介"),"season description");fails(()->PgcModels.season(new JSONObject()),"missing season id");
  JSONObject stream=new JSONObject().put("quality",32).put("durl",new JSONArray().put(new JSONObject().put("url","https://cdn.test/video.mp4")));check(PgcModels.stream(stream,0).quality==32,"available quality");stream.put("is_preview",1);check(PgcModels.stream(stream,0).label.startsWith("试看"),"trial explicit");stream.put("is_drm",true);fails(()->PgcModels.stream(stream,0),"protected stream unsupported");
  System.out.println("PASS: "+count+" PGC cases: identity, catalogs, episodes, permissions, formats and pagination");
 }
}
